INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400093521030110, ARRAY['"A team must diagnose slow file access. The drive has ample free space but latency is high and transfer rate is modest. Which approach is most technically sound?"'::jsonb, '"A PC uses a legacy parallel printer while a replacement desktop has only USB. What is the correct planning step?"'::jsonb, '"A dual-OS installation is needed on a laptop that already contains an operating system and user data. What is the safest plan?"'::jsonb, '"A technician identifies an old CRT and a newer LCD monitor. Which physical operating principle distinguishes the CRT?"'::jsonb, '"A computer boots, but an attached USB keyboard fails only on one front-panel port. The rear ports work. What does the evidence most strongly suggest?"'::jsonb, '"A laptop''s fan is noisy after dust cleanup, and ventilation is clear. Which next step is the most responsible?"'::jsonb, '"A new hard drive must be divided into a system partition and a data partition. Which sequence is accurate at a high level?"'::jsonb, '"A motherboard provides a suitable slot, but the installed graphics card is not detected and needs extra power. What order should troubleshooting follow?"'::jsonb, '"A repair involves a power connector with male/female contacts. Why should the connector type and orientation be verified before applying power?"'::jsonb, '"A laptop''s internal graphics card is integrated into the system board, while another model has a discrete graphics card. Which conclusion is safest?"'::jsonb]::jsonb[], ARRAY['"Measure access time and transfer rate separately and compare them with the workload and drive specifications"'::jsonb, '"Conclude capacity is the only performance metric"'::jsonb, '"Replace the monitor first"'::jsonb, '"Use printer resolution to estimate drive speed"'::jsonb, '"Check whether a compatible parallel-to-USB interface and required driver are supported"'::jsonb, '"Connect the parallel plug into HDMI"'::jsonb, '"Assume every legacy interface is natively supported"'::jsonb, '"Replace RAM with a printer adapter"'::jsonb, '"Back up, verify hardware/OS compatibility and partition layout, then configure boot selection before installation"'::jsonb, '"Delete all partitions without reviewing the disk"'::jsonb, '"Install both systems to the same partition without checking support"'::jsonb, '"Disable all boot security permanently as the first step"'::jsonb, '"An electron beam excites phosphor on the screen"'::jsonb, '"Liquid crystals modulate light"'::jsonb, '"A flash-memory cell stores every pixel permanently"'::jsonb, '"Ink droplets form each image"'::jsonb, '"A problem with that front-panel port, its cable or connection, rather than a complete keyboard failure"'::jsonb, '"Every keyboard key is defective"'::jsonb, '"The hard drive must be partitioned"'::jsonb, '"The monitor uses the wrong resolution"'::jsonb, '"Power down and inspect fan mounting/obstruction or seek service if the noise persists"'::jsonb, '"Increase processor load until noise stops"'::jsonb, '"Block the fan outlet"'::jsonb, '"Format the drive to fix sound"'::jsonb, '"Initialize/partition the intended disk as required, format each intended partition with a file system, then assign/use them"'::jsonb, '"Format before deciding which disk is intended"'::jsonb, '"Change the monitor input, then create partitions"'::jsonb, '"Install a printer cartridge to create a file system"'::jsonb, '"Verify card seating/slot compatibility and required power connection, then inspect firmware and drivers"'::jsonb, '"Reformat all disks immediately"'::jsonb, '"Change mouse sensitivity"'::jsonb, '"Replace the keyboard membrane"'::jsonb, '"Incorrect or mismatched power connections can damage components and create safety risks"'::jsonb, '"Connector shape changes file names"'::jsonb, '"It changes the display''s pixel count"'::jsonb, '"It alters the keyboard language automatically"'::jsonb, '"Design and upgrade options depend on the particular laptop; a discrete card is not automatically user-replaceable"'::jsonb, '"Every graphics card can be removed like a USB drive"'::jsonb, '"Integrated graphics always require a separate display cable"'::jsonb, '"A graphics subsystem changes hard-drive formatting"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400093521030111, ARRAY['"A disk has capacity 1 TB, but the OS displays only one 200 GB volume and the rest appears unallocated. What is the likely explanation?"'::jsonb, '"A PC will not start after a motherboard installation. The outlet works and fans spin, but no display appears. Which staged diagnostic is best?"'::jsonb, '"A computer needs a quiet printer for ordinary office documents and a separate printer for multi-part forms. Which pairing is most suitable?"'::jsonb, '"A technician plans to format a disk because the OS cannot read its partition. What evidence should be checked first?"'::jsonb, '"A laptop is connected to a display through HDMI, and audio is also routed to the display. Which explanation is correct?"'::jsonb, '"A workstation loses time/date settings when disconnected from mains power, but boots otherwise. Which area is worth checking?"'::jsonb, '"A hardware report confuses memory capacity with disk access time. Which correction is exact?"'::jsonb, '"An optical drive reads a DVD but not a CD-RW. What should be checked before replacing the entire motherboard?"'::jsonb, '"A technician must install a second hard drive in a desktop. Which combination must generally be available?"'::jsonb, '"After keyboard cleaning, a key is physically stuck but the keyboard still enumerates normally. Which diagnosis is most targeted?"'::jsonb]::jsonb[], ARRAY['"The disk may have additional unallocated space that has not been assigned to a partition/volume"'::jsonb, '"The remaining space is definitely CPU cache"'::jsonb, '"The monitor limits disk capacity"'::jsonb, '"The printer has hidden the other partitions"'::jsonb, '"Recheck internal power connectors, RAM/graphics seating and firmware/hardware indicators one change at a time"'::jsonb, '"Format the old hard drive first"'::jsonb, '"Replace every peripheral at once"'::jsonb, '"Change document page margins"'::jsonb, '"Inkjet for quiet non-impact output; dot-matrix for impact multi-part forms"'::jsonb, '"Dot-matrix for both because it is non-impact"'::jsonb, '"Inkjet for multipart impact forms; HDD for paper output"'::jsonb, '"CRT monitor and microphone"'::jsonb, '"Confirm the disk identity, backup status and whether data recovery is needed before any destructive action"'::jsonb, '"Assume unreadable means empty"'::jsonb, '"Format all connected drives to test them"'::jsonb, '"Remove the PSU fan to improve reading"'::jsonb, '"HDMI can carry digital video and audio, subject to device support and settings"'::jsonb, '"HDMI carries only keyboard commands"'::jsonb, '"HDMI is a magnetic storage format"'::jsonb, '"HDMI is used only for printer ribbons"'::jsonb, '"RTC/CMOS battery and firmware configuration retention"'::jsonb, '"Mouse wheel encoder"'::jsonb, '"Printer nozzle"'::jsonb, '"Optical drive tray"'::jsonb, '"Capacity is the amount that can be stored; access time is the delay to retrieve/access data"'::jsonb, '"Both measure the screen size"'::jsonb, '"Access time is the number of USB ports"'::jsonb, '"Capacity is the speed at which a mouse moves"'::jsonb, '"Drive support/compatibility, disc condition and the correct driver or connection path"'::jsonb, '"CPU arithmetic logic"'::jsonb, '"Keyboard layout"'::jsonb, '"PSU outlet gender only"'::jsonb, '"Compatible drive bay/mounting, data interface connection and suitable power connection"'::jsonb, '"Only a free mouse button"'::jsonb, '"A printer ribbon and speaker grille"'::jsonb, '"A display-resolution menu only"'::jsonb, '"Mechanical key/switch or reassembly issue"'::jsonb, '"Hard-disk partition table"'::jsonb, '"Monitor refresh rate"'::jsonb, '"Network domain resolution"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400093521030112, ARRAY['"A drive is missing from the OS after a cable replacement. It is absent in firmware as well. Which conclusion is most justified?"'::jsonb, '"A laptop overheats only when used on a blanket and works better on a hard table. Which mechanism best explains the pattern?"'::jsonb, '"A hard disk upgrade is required while keeping the existing operating system and documents. Which plan best balances installation and data risk?"'::jsonb, '"A monitor works at low resolution but shows no image at a selected higher mode. What is the first sensible correction?"'::jsonb, '"A technician must connect a legacy serial device and a modern USB device. Which principle governs the connection choice?"'::jsonb, '"A system offers integrated graphics and a discrete expansion-card option. What should guide choosing the discrete card?"'::jsonb, '"A technician has to identify whether a device is magnetic, optical or flash storage. Which trio is mapped correctly?"'::jsonb, '"A hard disk''s measured transfer rate is good but response to many small random requests is slow. Which additional metric should be inspected?"'::jsonb, '"A PC''s keyboard and mouse are not detected on PS/2 ports but do work over USB. What is the most targeted next check?"'::jsonb, '"A repair is complete and the PC boots, but one fan remains disconnected. What should the technician do before returning the system?"'::jsonb]::jsonb[], ARRAY['"Investigate power/data cabling, drive compatibility or hardware failure before OS partition steps"'::jsonb, '"The drive only needs a file-system label"'::jsonb, '"The display cable is definitely at fault"'::jsonb, '"The keyboard must be reinstalled"'::jsonb, '"The blanket may obstruct intake/exhaust airflow, reducing cooling"'::jsonb, '"The hard table doubles RAM capacity"'::jsonb, '"The screen resolution changes battery chemistry"'::jsonb, '"The keyboard changes the CPU''s instruction set"'::jsonb, '"Back up data, verify the new drive/interface, install with power disconnected, detect it, then partition/format only the new disk if required"'::jsonb, '"Format the current drive before testing the new one"'::jsonb, '"Disconnect the old disk while the computer is running regardless of support"'::jsonb, '"Copy files after erasing the only disk"'::jsonb, '"Return to a supported resolution and verify input/cable compatibility"'::jsonb, '"Format the HDD"'::jsonb, '"Replace the keyboard switches"'::jsonb, '"Use a dot-matrix driver"'::jsonb, '"Match each peripheral''s interface with a supported computer port/adapter and driver"'::jsonb, '"Any connector can carry any data if forced"'::jsonb, '"Use the monitor port for serial data"'::jsonb, '"Choose only by connector colour"'::jsonb, '"Required graphics workload, compatibility, physical fit, power and cooling capacity"'::jsonb, '"Whether the mouse is wireless"'::jsonb, '"Whether the printer uses impact dots"'::jsonb, '"How many partitions are on the hard disk"'::jsonb, '"HDD—magnetic; DVD—optical; USB flash drive—flash memory"'::jsonb, '"HDD—optical; DVD—flash; USB drive—magnetic platter"'::jsonb, '"RAM—optical; HDD—CPU cache; DVD—magnetic card"'::jsonb, '"USB drive—CRT; DVD—RAM; HDD—keyboard"'::jsonb, '"Access time"'::jsonb, '"Pixel density"'::jsonb, '"Speaker frequency"'::jsonb, '"Keyboard switch force"'::jsonb, '"PS/2 port/device support, port condition and firmware settings"'::jsonb, '"Disk capacity"'::jsonb, '"Printer paper tray"'::jsonb, '"Optical disc colour"'::jsonb, '"Power down and reconnect/verify the fan, then test cooling and stability"'::jsonb, '"Leave it disconnected if the PC starts"'::jsonb, '"Run a long stress test while overheated"'::jsonb, '"Format user files"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb]::jsonb[]);
COMMIT;
